WITH base AS (SELECT *, CASE WHEN location = 'London' THEN 1 ELSE 0 END AS is_london, COALESCE(dept_name, 'UNKNOWN') AS resolved_dept_name FROM departments WHERE location IS NOT NULL) SELECT id, dept_name, location, budget, STDDEV_SAMP(is_london) OVER (PARTITION BY dept_name, location) AS dept_name_stddev_samp_is_london, SUM(is_london) OVER (PARTITION BY location, dept_name ORDER BY is_london, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_is_london FROM base WHERE location = 'Tokyo';
